export const COMPONENT_ICONS: Record<string, string> = {
  ...AWS_ICONS,
  ...TILE_ICONS,
  ...FALLBACK_ICONS,
};

/** Resolve a content icon id to a registry key, falling back to the category tile
 *  when the id is unknown (FR-007). Checks COMPONENT_ICONS to avoid an icon.registry cycle. */
export function componentIconName(icon: string, category: Category): string {
  return icon in COMPONENT_ICONS ? icon : `fallback-${category}`;
}
